<?php
declare(strict_types=1);
namespace ReadyFinance;
/** Corrections append balanced journals. Original postings are never rewritten. */
final class TransactionEditingService {
 public function __construct(private Core $c){}
 public function details(int $h,string $uuid):array {
  $c=$this->c;$t=$c->scope('transactions',$uuid,$h);$rows=$c->all('SELECT jl.*,l.uuid ledger_uuid,l.class,a.uuid money_uuid,o.uuid obligation_uuid FROM journal_lines jl JOIN journal_entries j ON j.id=jl.journal_id JOIN ledger_accounts l ON l.id=jl.ledger_id AND l.household_id=jl.household_id LEFT JOIN accounts a ON a.ledger_id=l.id AND a.household_id=l.household_id LEFT JOIN obligations o ON o.ledger_id=l.id AND o.household_id=l.household_id WHERE j.transaction_id=? AND jl.household_id=? ORDER BY jl.id',[$t['id'],$h]);
  $p=['type'=>$t['type'],'date'=>$t['effective_date'],'description'=>$t['description'],'amount'=>$t['amount']];
  foreach($rows as $row){if($row['money_uuid']){if($t['type']==='transfer'&&bccomp($row['debit'],'0',6)>0)$p['to_account_uuid']=$row['money_uuid'];else $p['account_uuid']=$row['money_uuid'];}if($row['obligation_uuid'])$p['obligation_uuid']=$row['obligation_uuid'];}
  $splits=$c->all('SELECT ca.uuid category_uuid,m.uuid member_uuid,s.amount,s.project,s.tags FROM transaction_splits s JOIN categories ca ON ca.id=s.category_id AND ca.household_id=s.household_id LEFT JOIN members m ON m.id=s.member_id AND m.household_id=s.household_id WHERE s.household_id=? AND s.transaction_id=? ORDER BY s.id',[$h,$t['id']]);
  if($splits){$p+=$splits[0];if(count($splits)>1)$p['splits']=$splits;}
  $bill=$c->one('SELECT b.uuid FROM bill_allocations ba JOIN bills b ON b.id=ba.bill_id AND b.household_id=ba.household_id WHERE ba.household_id=? AND ba.transaction_id=? AND ba.amount>0',[$h,$t['id']]);if($bill)$p['bill_uuid']=$bill['uuid'];
  $p['lines']=array_map(fn($r)=>['account_uuid'=>$r['ledger_uuid'],'debit'=>$r['debit'],'credit'=>$r['credit']],$rows);
  return ['transaction'=>$t,'payload'=>$p];
 }
 public function edit(int $h,int $u,array $input,string $key):array {
  if(!(new AccountManagementService($this->c))->ready())throw new Fault('Enable editing and review tools first.');
  if(!preg_match('/^[a-zA-Z0-9_.:-]{8,150}$/D',$key))throw new Fault('A valid command key is required.');
  return $this->c->atomic(fn()=>$this->editInTransaction($h,$u,$input,$key));
 }
 public function editInTransaction(int $h,int $u,array $input,string $key):array {
  $c=$this->c;$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$hash=hash('sha256',json_encode($input,JSON_THROW_ON_ERROR));$command='edit:'.$key;
  $old=$c->one('SELECT * FROM command_receipts WHERE household_id=? AND command_key=?',[$h,$command]);if($old){if(!hash_equals($old['payload_hash'],$hash))throw new Fault('Command key conflict.',409);return json_decode($old['result_json'],true,32,JSON_THROW_ON_ERROR);}
  $t=$c->scope('transactions',(string)($input['uuid']??''),$h,true);if($t['status']!=='posted'||$t['type']==='reversal')throw new Fault('This entry has already been changed or reversed. Refresh the list.',409);if((string)($input['row_version']??'')!==(string)$t['row_version'])throw new Fault('The entry changed while you were editing. Refresh and try again.',409);
  $reason=Core::text($input['reason']??'',400);$p=$input['payload']??null;if(!is_array($p))throw new Fault('Correction details are required.');$original=$this->details($h,$t['uuid'])['payload'];
  if(in_array($t['type'],['expense','income','refund','transfer'],true)){if(!in_array($p['type']??'', ['expense','income','refund','transfer'],true))throw new Fault('Choose an everyday transaction type.');}elseif(($p['type']??'')!==$t['type'])throw new Fault('Keep the original transaction type for this correction.');
  if(isset($original['bill_uuid'])){if(($p['bill_uuid']??'')!==$original['bill_uuid'])throw new Fault('Keep the original bill linked to this payment.');}elseif(!empty($p['bill_uuid']))throw new Fault('This entry was not a bill payment.');
  if(isset($original['obligation_uuid'])&&($p['obligation_uuid']??'')!==$original['obligation_uuid'])throw new Fault('Keep the original loan linked to this correction.');
  $date=Core::date($p['date']??'');$c->guardPeriod($h,$t['effective_date']);$c->guardPeriod($h,$date);
  $engine=new Accounting($c);$reversal=$engine->reverseInTransaction($h,$u,$t['uuid'],$t['effective_date'],$reason,'edit-reverse:'.$key,false);
  $replacement=$t['type']==='journal'?$engine->postJournalInTransaction($h,$u,$p,'edit-post:'.$key):$engine->postInTransaction($h,$u,$p,'edit-post:'.$key);
  foreach($c->all('SELECT ledger_id,direction FROM obligations WHERE household_id=?',[$h]) as $ob){$balance=$c->balance($h,(int)$ob['ledger_id']);if(($ob['direction']==='borrowed'&&bccomp($balance,'0',6)>0)||($ob['direction']==='lent'&&bccomp($balance,'0',6)<0))throw new Fault('The correction would overpay a loan. Correct related repayments first.',409);}
  if(in_array($t['type'],['borrow','lend'],true)){$ob=$c->scope('obligations',$original['obligation_uuid'],$h);$c->query('UPDATE obligations SET original_amount=? WHERE household_id=? AND id=?',[$replacement['amount'],$h,$ob['id']]);}
  if($c->query("SELECT COUNT(*) FROM schema_migrations WHERE version='004_statement_import'")->fetchColumn()){
   foreach($c->all('SELECT il.account_id,a.ledger_id FROM import_links il JOIN accounts a ON a.id=il.account_id AND a.household_id=il.household_id WHERE il.household_id=? AND il.transaction_id=?',[$h,$t['id']]) as $link){$effect=fn($id)=>(string)$c->query('SELECT COALESCE(SUM(jl.debit-jl.credit),0) FROM journal_lines jl JOIN journal_entries j ON j.id=jl.journal_id WHERE jl.household_id=? AND j.transaction_id=? AND jl.ledger_id=?',[$h,$id,$link['ledger_id']])->fetchColumn();if($date!==$t['effective_date']||bccomp($effect($t['id']),$effect($replacement['id']),6)!==0)throw new Fault('This entry is matched to a bank statement. Keep its date and bank amount unchanged; you can correct its category and note.',409);}
   $c->query('UPDATE import_links SET transaction_id=? WHERE household_id=? AND transaction_id=?',[$replacement['id'],$h,$t['id']]);$c->query('UPDATE import_rows SET transaction_id=? WHERE household_id=? AND transaction_id=?',[$replacement['id'],$h,$t['id']]);
  }
  $c->query('UPDATE documents SET transaction_id=? WHERE household_id=? AND transaction_id=?',[$replacement['id'],$h,$t['id']]);
  $c->query('UPDATE transactions SET replaces_id=?,edit_reason=? WHERE household_id=? AND id=?',[$t['id'],$reason,$h,$replacement['id']]);
  $result=['uuid'=>$replacement['uuid'],'original_uuid'=>$t['uuid'],'reversal_uuid'=>$reversal['uuid']];$c->insert('command_receipts',['household_id'=>$h,'command_key'=>$command,'payload_hash'=>$hash,'result_json'=>json_encode($result,JSON_THROW_ON_ERROR),'created_at'=>Core::now()]);$c->audit($h,$u,'transaction.edited',$t['uuid'],$result+['reason'=>$reason]);return $result;
 }
 public function moveCategory(int $h,int $u,array $p,string $key):array {
  $c=$this->c;if(!(new AccountManagementService($c))->ready())throw new Fault('Enable editing tools first.');if(!preg_match('/^[a-zA-Z0-9_.:-]{8,100}$/D',$key))throw new Fault('Command key required.');
  return $c->atomic(function()use($c,$h,$u,$p,$key){$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$command='move-category:'.$key;$hash=hash('sha256',json_encode($p,JSON_THROW_ON_ERROR));$old=$c->one('SELECT * FROM command_receipts WHERE household_id=? AND command_key=?',[$h,$command]);if($old){if($old['payload_hash']!==$hash)throw new Fault('Command key conflict.',409);return json_decode($old['result_json'],true);}
   $source=$c->scope('categories',(string)($p['source_uuid']??''),$h);$target=$c->scope('categories',(string)($p['target_uuid']??''),$h);if($source['id']===$target['id']||$source['type']!==$target['type'])throw new Fault('Choose a different account of the same income or expense type.');$ledger=$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$target['ledger_id']]);if(!$ledger['active'])throw new Fault('Choose an active destination.');$reason=Core::text($p['reason']??'',400);
   $transactions=$c->all("SELECT DISTINCT t.* FROM transactions t JOIN transaction_splits s ON s.transaction_id=t.id AND s.household_id=t.household_id WHERE t.household_id=? AND t.status='posted' AND t.type<>'reversal' AND s.category_id=? ORDER BY t.id LIMIT 101",[$h,$source['id']]);if(count($transactions)>100)throw new Fault('This account has more than 100 current transactions. Edit them in smaller selections before archiving.');
   // Preserve planning rows; explicitly combine budgets instead of requiring DELETE privileges.
   foreach($c->all('SELECT * FROM budgets WHERE household_id=? AND category_id=?',[$h,$source['id']]) as $budget){$other=$c->one('SELECT * FROM budgets WHERE household_id=? AND category_id=? AND month=?',[$h,$target['id'],$budget['month']]);if($other){if(($p['combine_budgets']??false)!==true)throw new Fault('Both categories have a budget in the same month. Select Combine budgets to add their planned amounts.');$c->query('UPDATE budgets SET amount=? WHERE household_id=? AND id=?',[bcadd($other['amount'],$budget['amount'],6),$h,$other['id']]);$c->query('UPDATE budgets SET amount=0 WHERE household_id=? AND id=?',[$h,$budget['id']]);}else $c->query('UPDATE budgets SET category_id=? WHERE household_id=? AND id=?',[$target['id'],$h,$budget['id']]);}
   foreach(['bills','recurring_rules'] as $table)$c->query('UPDATE '.$table.' SET category_id=? WHERE household_id=? AND category_id=?',[$target['id'],$h,$source['id']]);
   foreach($transactions as $t){$payload=$this->details($h,$t['uuid'])['payload'];$payload['category_uuid']=$target['uuid'];if(isset($payload['splits']))foreach($payload['splits'] as &$split){if($split['category_uuid']===$source['uuid'])$split['category_uuid']=$target['uuid'];}unset($split);$this->editInTransaction($h,$u,['uuid'=>$t['uuid'],'row_version'=>$t['row_version'],'reason'=>$reason,'payload'=>$payload],$key.':'.$t['id']);}
   // Manual journals use ledger lines rather than transaction splits; move them too.
   $journals=$c->all("SELECT DISTINCT t.* FROM transactions t JOIN journal_entries j ON j.transaction_id=t.id JOIN journal_lines l ON l.journal_id=j.id WHERE t.household_id=? AND l.ledger_id=? AND t.type='journal' AND t.status='posted' LIMIT 101",[$h,$source['ledger_id']]);if(count($journals)+count($transactions)>100)throw new Fault('Move at most 100 current entries at a time.');foreach($journals as $t){$payload=$this->details($h,$t['uuid'])['payload'];$sourceLedger=$c->one('SELECT uuid FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$source['ledger_id']]);foreach($payload['lines'] as &$line)if($line['account_uuid']===$sourceLedger['uuid'])$line['account_uuid']=$ledger['uuid'];unset($line);$this->editInTransaction($h,$u,['uuid'=>$t['uuid'],'row_version'=>$t['row_version'],'reason'=>$reason,'payload'=>$payload],$key.':'.$t['id']);}
   if(($p['archive']??false)===true){$sourceLedger=$c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$source['ledger_id']]);if(!empty($sourceLedger['system_key']))throw new Fault('Required system categories cannot be archived.');$c->query('UPDATE ledger_accounts SET active=0 WHERE household_id=? AND id=?',[$h,$source['ledger_id']]);$c->audit($h,$u,'account.archive',$sourceLedger['uuid'],['moved_to'=>$target['uuid']]);}$result=['moved'=>count($transactions)+count($journals),'archived'=>($p['archive']??false)===true];$c->insert('command_receipts',['household_id'=>$h,'command_key'=>$command,'payload_hash'=>$hash,'result_json'=>json_encode($result),'created_at'=>Core::now()]);$c->audit($h,$u,'category.entries_moved',$source['uuid'],$p+['moved'=>$result['moved']]);return $result;
  });
 }
}
